-- The event module's own table (D-033, D-040): id generated by PostgreSQL 18's uuidv7(),
-- read back via RETURNING. CHECK constraints mirror the contract's own bounds
-- (contracts/openapi.yaml, CreateEventRequest) as a safety net below the application layer.
-- No CHECK uses now(): the sale-opening-margin rule is enforced in the insert itself
-- (ADR 0040), not as a table constraint, since it depends on the moment of the insert.
CREATE TABLE event.event (
    id                    uuid PRIMARY KEY DEFAULT uuidv7(),
    name                  varchar(200) NOT NULL CHECK (char_length(name) >= 1),
    description           varchar(2000),
    capacity              integer NOT NULL CHECK (capacity BETWEEN 1 AND 1000000),
    sale_start_time       timestamptz NOT NULL,
    event_date            timestamptz NOT NULL,
    hold_duration_seconds integer NOT NULL CHECK (hold_duration_seconds BETWEEN 60 AND 3600),
    created_at            timestamptz NOT NULL DEFAULT now(),
    CHECK (sale_start_time < event_date)
);
